const A='/api/index?action=',S={page:'projects',connected:false,hubs:[],hub:'',projects:[],companies:[],users:[],members:[],selProjects:new Set(),selUsers:new Set(),selMembers:new Set(),preview:[],results:[],search:''};const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),api=async(a,o={})=>{const r=await fetch(A+a,{credentials:'include',headers:{'Content-Type':'application/json'},...o}),d=await r.json().catch(()=>({message:r.statusText}));if(!r.ok)throw new Error(d.message);return d},tbl=(h,r)=>`<div class="table"><table><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${r.length?r.map(x=>`<tr>${x.map(v=>`<td>${v??''}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${h.length}">No records.</td></tr>`}</tbody></table></div>`;
function render(){const n=[['projects','Project Names'],['companies','Companies'],['access','Users & Access'],['bulk','Bulk User Company'],['reports','Reports']];$('#app').innerHTML=`<div class="layout"><aside class="side"><div class="brand">Company Manage v29</div><div class="nav">${n.map(x=>`<button data-p="${x[0]}" class="${S.page===x[0]?'on':''}">${x[1]}</button>`).join('')}</div></aside><main class="main"><div class="head"><h1>${n.find(x=>x[0]===S.page)[1]}</h1><button id="auth" class="btn">${S.connected?'Sign out':'Connect Autodesk'}</button></div><div id="err"></div><div class="card bar"><b>Hub</b><select id="hub" class="select grow">${S.hubs.map(h=>`<option value="${h.id}" ${h.id===S.hub?'selected':''}>${esc(h.name)}</option>`).join('')}</select></div>${view()}</main></div>`;bind()}
function view(){if(S.page==='projects')return projectView();if(S.page==='companies')return listView('companies');if(S.page==='access')return accessView();if(S.page==='bulk')return bulkView();return `<div class="card"><button id="exportResults" class="btn">Export Results Excel</button>${tbl(['Type','Name','Original','Proposed','Result','Error'],S.results.map(r=>[r.type,r.name,r.original,r.proposed,r.result,r.error]))}</div>`}
function projectView(){const q=S.search.toLowerCase(),rows=S.projects.filter(p=>[p.name,p.jobNumber,p.status,p.id].some(v=>String(v).toLowerCase().includes(q))),prev=new Map(S.preview.map(p=>[p.id,p]));return `<div class="card"><div class="bar"><input id="search" class="input grow" placeholder="Search project name, number, status or ID" value="${esc(S.search)}"><button id="loadProjects" class="btn">Load Projects</button><button id="allProjects" class="btn soft">Select All Filtered</button><button id="clearProjects" class="btn light">Deselect All</button><span class="badge">${S.selProjects.size} selected</span></div><div class="bar"><select id="operation" class="select"><option value="addPrefix">Add Prefix</option><option value="removePrefix">Remove Prefix</option><option value="addSuffix">Add Suffix</option><option value="removeSuffix">Remove Suffix</option><option value="setJobNumber">Set Job Number</option></select><input id="value" class="input grow" placeholder="Prefix, suffix, or job number"><button id="preview" class="btn soft">Preview</button><button id="apply" class="btn">Apply BIM 360 Changes</button><button id="exportPreview" class="btn light">Export Preview</button></div><div class="notice">BIM 360 project updates use the HQ PATCH endpoint. ACC/Forma projects may be rejected and will remain unchanged with a reported error.</div>${tbl(['Select','Current Name','Project Number','Status','Platform','Proposed Name','Validation'],rows.map(p=>{const x=prev.get(p.id);return[`<input class="projectSelect" data-id="${p.id}" type="checkbox" ${S.selProjects.has(p.id)?'checked':''}>`,esc(p.name),esc(p.jobNumber),esc(p.status),esc(p.platform),esc(x?.proposedName||''),x?`<span class="${x.valid?'ok':'bad'}">${esc(x.validation)}</span>`:'']}))}</div>`}
function listView(){const q=S.search.toLowerCase(),rows=S.companies.filter(c=>[c.name,c.trade,c.erpId,c.taxId].some(v=>String(v).toLowerCase().includes(q)));return `<div class="card"><div class="bar"><input id="search" class="input grow" placeholder="Search companies" value="${esc(S.search)}"><button id="loadCompanies" class="btn">Load Companies</button></div>${tbl(['Company','Trade','ERP ID','Tax ID','Members','Projects'],rows.map(c=>[esc(c.name),esc(c.trade),esc(c.erpId),esc(c.taxId),c.members,c.projects]))}</div>`}
function accessView(){return `<div class="card"><button id="loadProjects" class="btn">Load Projects</button><button id="allProjects" class="btn soft">Select All</button><button id="clearProjects" class="btn light">Deselect All</button><button id="loadMembers" class="btn">Load Users</button>${tbl(['Select','Project','Status'],S.projects.map(p=>[`<input class="projectSelect" data-id="${p.id}" type="checkbox" ${S.selProjects.has(p.id)?'checked':''}>`,esc(p.name),esc(p.status)]))}</div><div class="card"><button id="allMembers" class="btn soft">Select All</button><button id="clearMembers" class="btn light">Deselect All</button><button id="removeMembers" class="btn danger">Remove From Projects</button>${tbl(['Select','Project','User','Email','Company','Roles'],S.members.map(m=>[`<input class="memberSelect" data-key="${m.key}" type="checkbox" ${S.selMembers.has(m.key)?'checked':''}>`,esc(m.projectName),esc(m.name),esc(m.email),esc(m.company),esc((m.roles||[]).map(r=>r.name||r).join(', '))]))}</div>`}
function bulkView(){return `<div class="card"><button id="loadUsers" class="btn">Load Hub Users</button><button id="loadCompanies" class="btn">Load Companies</button><button id="allUsers" class="btn soft">Select All</button><button id="clearUsers" class="btn light">Deselect All</button><select id="targetCompany" class="select grow"><option value="">Target company</option>${S.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><button id="applyCompany" class="btn">Apply Company Change</button>${tbl(['Select','User','Email','Current Company'],S.users.map(u=>[`<input class="userSelect" data-id="${u.id}" type="checkbox" ${S.selUsers.has(u.id)?'checked':''}>`,esc(u.name),esc(u.email),esc(u.company)]))}</div>`}
async function loadPaged(type){let out=[],o=0,total=1;while(o<total){const d=await api(`${type}-page&hubId=${encodeURIComponent(S.hub)}&offset=${o}`);out.push(...d.items);total=d.total;o=d.nextOffset}S[type==='hub-users'?'users':type]=out;render()}function preview(){const op=$('#operation').value,val=$('#value').value,res=[],names=new Set();for(const p of S.projects.filter(x=>S.selProjects.has(x.id))){let name=p.name,job=p.jobNumber;if(op==='addPrefix')name=val+name;if(op==='removePrefix'&&name.startsWith(val))name=name.slice(val.length);if(op==='addSuffix')name=name+val;if(op==='removeSuffix'&&name.endsWith(val))name=name.slice(0,-val.length);if(op==='setJobNumber')job=val;const invalid=/[\\/?\[\]>*:<"|,]/.test(name),dup=names.has(name.toLowerCase()),valid=!!name&&name.length<=255&&!invalid&&!dup&&String(job||'').length<=100;names.add(name.toLowerCase());res.push({...p,proposedName:name,proposedJobNumber:job,valid,validation:valid?'Ready':!name?'Empty name':invalid?'Reserved character':dup?'Duplicate proposed name':name.length>255?'Name over 255 characters':'Job number over 100 characters'})}S.preview=res;render()}
async function applyProjects(){const jobs=S.preview.filter(x=>x.valid),d=await api('projects-rename',{method:'POST',body:JSON.stringify({hubId:S.hub,projects:jobs})});for(const r of d.results)S.results.push({type:'Project Update',name:r.name,original:r.name,proposed:r.proposedName,result:r.success?'Success':r.unsupported?'Unsupported/Rejected':'Failed',error:r.error||''});const ok=new Map(d.results.filter(r=>r.success).map(r=>[r.id,r]));S.projects=S.projects.map(p=>ok.has(p.id)?{...p,name:ok.get(p.id).proposedName,jobNumber:ok.get(p.id).proposedJobNumber}:p);render()}
function exportX(name,data){const w=XLSX.utils.book_new();XLSX.utils.book_append_sheet(w,XLSX.utils.json_to_sheet(data),'Data');XLSX.writeFile(w,name)}
function bind(){document.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>{S.page=b.dataset.p;S.search='';render()});$('#auth').onclick=async()=>S.connected?(await api('auth-logout',{method:'POST'}),location.reload()):(location.href=(await api('auth-login')).url);$('#hub').onchange=e=>S.hub=e.target.value;if($('#search'))$('#search').oninput=e=>{S.search=e.target.value;render()};if($('#loadProjects'))$('#loadProjects').onclick=()=>loadPaged('projects');if($('#loadCompanies'))$('#loadCompanies').onclick=()=>loadPaged('companies');document.querySelectorAll('.projectSelect').forEach(x=>x.onchange=()=>x.checked?S.selProjects.add(x.dataset.id):S.selProjects.delete(x.dataset.id));if($('#allProjects'))$('#allProjects').onclick=()=>{S.projects.forEach(p=>S.selProjects.add(p.id));render()};if($('#clearProjects'))$('#clearProjects').onclick=()=>{S.selProjects.clear();render()};if($('#preview'))$('#preview').onclick=preview;if($('#apply'))$('#apply').onclick=applyProjects;if($('#exportPreview'))$('#exportPreview').onclick=()=>exportX('Project_Name_Change_Preview.xlsx',S.preview);if($('#loadMembers'))$('#loadMembers').onclick=async()=>{const projects=S.projects.filter(p=>S.selProjects.has(p.id)),d=await api('selected-project-users',{method:'POST',body:JSON.stringify({projects})});S.members=d.items;render()};document.querySelectorAll('.memberSelect').forEach(x=>x.onchange=()=>x.checked?S.selMembers.add(x.dataset.key):S.selMembers.delete(x.dataset.key));if($('#allMembers'))$('#allMembers').onclick=()=>{S.members.forEach(m=>S.selMembers.add(m.key));render()};if($('#clearMembers'))$('#clearMembers').onclick=()=>{S.selMembers.clear();render()};if($('#removeMembers'))$('#removeMembers').onclick=async()=>{const items=S.members.filter(m=>S.selMembers.has(m.key)),d=await api('members-remove',{method:'POST',body:JSON.stringify({items})});const ok=new Set(d.results.filter(r=>r.success).map(r=>r.key));S.members=S.members.filter(m=>!ok.has(m.key));render()};if($('#loadUsers'))$('#loadUsers').onclick=()=>loadPaged('hub-users');document.querySelectorAll('.userSelect').forEach(x=>x.onchange=()=>x.checked?S.selUsers.add(x.dataset.id):S.selUsers.delete(x.dataset.id));if($('#allUsers'))$('#allUsers').onclick=()=>{S.users.forEach(u=>S.selUsers.add(u.id));render()};if($('#clearUsers'))$('#clearUsers').onclick=()=>{S.selUsers.clear();render()};if($('#applyCompany'))$('#applyCompany').onclick=async()=>{const id=$('#targetCompany').value,users=S.users.filter(u=>S.selUsers.has(u.id));await api('bulk-user-company',{method:'POST',body:JSON.stringify({hubId:S.hub,companyId:id,users})});render()};if($('#exportResults'))$('#exportResults').onclick=()=>exportX('Company_Manage_Results.xlsx',S.results)}
async function start(){if(location.pathname==='/callback'){await api('auth-callback&code='+encodeURIComponent(new URLSearchParams(location.search).get('code')||''));location.replace('/');return}const d=await api('auth-status');S.connected=d.authenticated;if(S.connected){const h=await api('hubs');S.hubs=h.hubs;S.hub=h.hubs[0]?.id||''}render()}start().catch(e=>{render();$('#err').innerHTML=`<div class="error">${esc(e.message)}</div>`});
